/*
 * A343524  Palindromes with digits strictly increasing up to the middle
 *          digit.
 * https://oeis.org/A343524
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base, fini, full
 * Formula:   defined by enumeration of palindromes with digits strictly
 *            increasing up to the middle digit. The sequence is generated by
 *            listing all such palindromes in increasing numeric order
 * Range:     u8 n <= 30, u16 n <= 171, u32 n <= 757, u64 n <= 1023,
 *            u128 n <= 1023, big any n
 * Helpers:   cmp_uint128
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>
#include <stdlib.h>
#include "../utils/cmp_uint128.h"

/* Helper: comparison function for unsigned __int128 values, used by qsort. */

/* Build the entire cache of sequence values on first use. */
static void build_cache(seq_t **cache_ptr, size_t *len_ptr) {
    static const size_t TOTAL = (1U << 9) - 1;          /* 511 non‑empty digit sets */
    static const size_t CAP = 1 + 2 * TOTAL;            /* 1023 numbers including zero */

    /* Allocate temporary array for exact 128‑bit values. */
    unsigned __int128 *tmp = (unsigned __int128 *)malloc(CAP * sizeof(unsigned __int128));
    if (!tmp) abort();

    size_t idx = 0;
    tmp[idx++] = 0;                                     /* a(1) = 0 */

    /* Enumerate all non‑empty subsets of digits 1..9. */
    for (unsigned int mask = 1; mask < (1U << 9); ++mask) {
        /* Extract digits in ascending order. */
        int digits[9];
        int k = 0;
        for (int d = 1; d <= 9; ++d) {
            if (mask & (1U << (d - 1))) {
                digits[k++] = d;
            }
        }

        /* Even‑length palindrome (mirror all digits). */
        unsigned __int128 val = 0;
        for (int i = 0; i < k; ++i) val = val * 10 + digits[i];
        for (int i = k - 1; i >= 0; --i) val = val * 10 + digits[i];
        tmp[idx++] = val;

        /* Odd‑length palindrome (mirror excluding the middle digit). */
        val = 0;
        for (int i = 0; i < k; ++i) val = val * 10 + digits[i];
        for (int i = k - 2; i >= 0; --i) val = val * 10 + digits[i];
        tmp[idx++] = val;
    }

    /* Sort the 128‑bit values numerically. */
    qsort(tmp, CAP, sizeof(unsigned __int128), cmp_uint128);

    /* Allocate cache of type seq_t and fill it. */
    seq_t *cache = (seq_t *)malloc(CAP * sizeof(seq_t));
    if (!cache) abort();
    for (size_t i = 0; i < CAP; ++i) {
        cache[i] = (seq_t)tmp[i];
    }

    free(tmp);
    *cache_ptr = cache;
    *len_ptr   = CAP;
}

/* Main sequence function. */
seq_t a(idx_t n) {
    /* Lazy static initialization. */
    static seq_t *cache = NULL;
    static size_t cache_len = 0;

    if (!cache) {
        build_cache(&cache, &cache_len);
    }

    if (n == 0) return 0;   /* index < 1 is undefined, return 0 as safe default */

    /* Adjust 1‑based to 0‑based index. */
    idx_t idx = n - 1;
    if (idx >= cache_len) return 0;   /* out of range */

    return cache[idx];
}
